#!/usr/bin/env python3
"""Writes core/artifacts/pyc_opcodes_313.h from CPython 3.13's own opcode
module, so Cortex's 3.13 disassembly names come from the interpreter that
defines them. Run with Python 3.13:

    python3.13 tests/fixtures/format-more/make_pyc_opcodes.py
"""
import opcode, os, sys
assert sys.version_info[:2] == (3, 13), "generate with CPython 3.13"
root = os.path.dirname(os.path.dirname(os.path.dirname(os.path.dirname(os.path.abspath(__file__)))))
names = [opcode.opname[i] if i < len(opcode.opname) and not opcode.opname[i].startswith("<") else "" for i in range(256)]
caches = [opcode._inline_cache_entries.get(n, 0) if n else 0 for n in names]
lines = ["#pragma once", "// Generated by tests/fixtures/format-more/make_pyc_opcodes.py from CPython 3.13's",
         "// opcode module. Do not edit by hand.", "#include <cstdint>", "namespace cortex::artifacts::pyc313 {",
         f"constexpr uint8_t kExtendedArg = {opcode.EXTENDED_ARG};", f"constexpr uint8_t kHaveArgument = {opcode.HAVE_ARGUMENT};",
         "constexpr const char* kNames[256] = {"]
for i in range(0, 256, 8):
    lines.append("    " + " ".join('"%s",' % n for n in names[i:i + 8]))
lines += ["};", "constexpr uint8_t kCaches[256] = {"]
for i in range(0, 256, 32):
    lines.append("    " + ",".join(str(c) for c in caches[i:i + 32]) + ",")
hasarg = [1 if i in opcode.hasarg else 0 for i in range(256)]
lines += ["};", "constexpr uint8_t kHasArg[256] = {"]
for i in range(0, 256, 32):
    lines.append("    " + ",".join(str(c) for c in hasarg[i:i + 32]) + ",")
lines += ["};", "} // namespace cortex::artifacts::pyc313", ""]
with open(os.path.join(root, "core", "artifacts", "pyc_opcodes_313.h"), "w") as f:
    f.write("\n".join(lines))
print("ok")
